BEGIN;
CREATE SCHEMA IF NOT EXISTS f2_import;
REVOKE ALL ON SCHEMA f2_import FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS f2_import.clasificaciones_fuente (
 tipo text NOT NULL,fecha date NOT NULL,ronda text NOT NULL,circuito_fuente text NOT NULL,
 numero_fuente text NOT NULL,piloto_fuente text NOT NULL,equipo_fuente text NOT NULL,datos jsonb NOT NULL,
 PRIMARY KEY(tipo,fecha,ronda,circuito_fuente,numero_fuente,piloto_fuente,datos)
);
ALTER TABLE f2_import.clasificaciones_fuente ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE f2_import.clasificaciones_fuente FROM PUBLIC,anon,authenticated;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
COMMIT;
SELECT tipo,count(*) AS filas FROM f2_import.clasificaciones_fuente WHERE extract(year from fecha)=2019 GROUP BY tipo ORDER BY tipo;
